suppressPackageStartupMessages({library(dplyr);library(ggplot2);library(jsonlite);library(optparse)})
options<-list(make_option(c("--aibl_file"),type="character",default="./analysis_pipeline/outputs/aibl_reduced_clinical_performance.csv"),make_option(c("--habs_file"),type="character",default="./step16_results/step16_performance_summary.csv"),make_option(c("--holdout_file"),type="character",default="./AI_vs_Clinician_Analysis/AI_test_results.json"),make_option(c("--output_dir"),type="character",default="./step18_results"))
opt<-parse_args(OptionParser(option_list=options));dir.create(opt$output_dir,recursive=TRUE,showWarnings=FALSE)
rows<-list()
if(file.exists(opt$holdout_file)){x<-fromJSON(opt$holdout_file);rows[[length(rows)+1]]<-data.frame(Cohort="ADNI independent test",Analysis="Frozen supervised prediction",N=x$N_test,Events=x$N_converters,AUC=x$AUC,CI_Lower=x$AUC_95CI_Lower,CI_Upper=x$AUC_95CI_Upper)}
if(file.exists(opt$aibl_file)){x<-read.csv(opt$aibl_file)%>%filter(Dataset=="AIBL_strict36",Calibration=="raw");if(nrow(x))rows[[length(rows)+1]]<-data.frame(Cohort="AIBL",Analysis="Frozen reduced clinical proxy",N=x$N[1],Events=x$Events[1],AUC=x$AUC[1],CI_Lower=x$AUC_CI_Lower[1],CI_Upper=x$AUC_CI_Upper[1])}
if(file.exists(opt$habs_file)){x<-read.csv(opt$habs_file)%>%filter(Stratum=="HABS_pTau217_Subset_Reduced_Clinical_plus_pTau217");if(nrow(x))rows[[length(rows)+1]]<-data.frame(Cohort="HABS",Analysis="Cohort-specific clinical plus p-tau217 framework",N=x$N[1],Events=x$Events[1],AUC=x$AUC[1],CI_Lower=x$CI_Lower[1],CI_Upper=x$CI_Upper[1])}
summary<-bind_rows(rows);if(!nrow(summary))stop("No evaluation summaries found.");write.csv(summary,file.path(opt$output_dir,"Evidence_Synthesis_Table.csv"),row.names=FALSE)
ggsave(file.path(opt$output_dir,"Figure_AUC_Summary.png"),ggplot(summary,aes(reorder(Cohort,AUC),AUC,color=Analysis,size=N))+geom_point()+geom_errorbar(aes(ymin=CI_Lower,ymax=CI_Upper),width=.12)+coord_flip()+theme_minimal()+ylim(.4,1),width=9,height=5,dpi=300)
writeLines(c("Structured evidence synthesis",apply(summary,1,function(z)sprintf("%s: %s; AUC %s (%s-%s)",z[["Cohort"]],z[["Analysis"]],z[["AUC"]],z[["CI_Lower"]],z[["CI_Upper"]]))),file.path(opt$output_dir,"Evidence_Synthesis_Report.txt"))
cat("Saved evidence synthesis outputs\n")
